def inc(x: int) -> int:
    return x + 1

def main() -> int:
    xs: list[int] = [1, 2, 3]
    res: list[int] = list(map(inc, xs))
    return res[0]

def is_pos(x: int) -> bool:
    return x > 0

def main() -> int:
    xs: list[int] = [-1, 2, 3]
    res: list[int] = list(filter(is_pos, xs))
    return res[0]
